let p = 0;
const N = data[p++];
const M = data[p++];

const slopeBIT = new Float64Array(N + 2);
const interceptBIT = new Float64Array(N + 2);

function add(bit, index, value) {
  for (let i = index; i <= N; i += i & -i) bit[i] += value;
}

function rangeAdd(bit, left, right, value) {
  add(bit, left, value);
  if (right < N) add(bit, right + 1, -value);
}

function pointQuery(bit, index) {
  let sum = 0;
  for (let i = index; i > 0; i -= i & -i) sum += bit[i];
  return sum;
}

const output = [];

for (let k = 0; k < M; k++) {
  const type = data[p++];
  const i = data[p++];

  if (type === 1) {
    const V = data[p++];
    const right = Math.min(N, i + V - 1);
    rangeAdd(slopeBIT, i, right, -1);
    rangeAdd(interceptBIT, i, right, V + i);
  } else if (type === 2) {
    const V = data[p++];
    const left = Math.max(1, i - V + 1);
    rangeAdd(slopeBIT, left, i, 1);
    rangeAdd(interceptBIT, left, i, V - i);
  } else {
    const slope = pointQuery(slopeBIT, i);
    const intercept = pointQuery(interceptBIT, i);
    output.push(String(slope * i + intercept));
  }
}

